impl Prefs {
    /// Typed `resize_to_video`.
    #[must_use]
    pub fn resize_to_video_mode(&self) -> crate::ResizeToVideo {
        crate::ResizeToVideo::parse(&self.resize_to_video)
    }

    /// Typed `continue_mode`.
    #[must_use]
    pub fn continue_playback_mode(&self) -> crate::ContinueMode {
        crate::ContinueMode::parse(&self.continue_mode)
    }

    /// Typed `deinterlace`.
    #[must_use]
    pub fn deinterlace_mode(&self) -> crate::DeinterlaceMode {
        crate::DeinterlaceMode::parse(&self.deinterlace)
    }

    /// Typed `hw_accel_mode`.
    #[must_use]
    pub fn hw_accel_mode_typed(&self) -> crate::HwAccelModePref {
        crate::HwAccelModePref::parse(&self.hw_accel_mode)
    }
}

