/// Cycle a string preference through its known option list.
pub fn cycle_pref_str(key: &str, current: &str) -> Option<&'static str> {
    let opts = pref_options(key);
    if opts.is_empty() {
        return None;
    }
    let idx = opts.iter().position(|o| *o == current).unwrap_or(0);
    Some(opts[(idx + 1) % opts.len()])
}
